tool_input.command:
mkdir -p /tmp/chk && cat > /tmp/chk/check.mjs <<'EOF'
import { chromium } from "/Users/alitahseen/Demos/chess-test.wt/r2-C/node_modules/@playwright/test/index.mjs";
import fs from "node:fs";
const base = `http://localhost:${process.env.PORT}`;
const puzzles = JSON.parse(fs.readFileSync("/Users/alitahseen/Demos/chess-test.wt/r2-C/public/puzzles.json","utf8"));
const b = await chromium.launch();
const errs=[];
const ctx = await b.newContext({viewport:{width:390,height:844},hasTouch:true,colorScheme:"dark"});
const page = await ctx.newPage();
page.on("console",m=>m.type()==="error"&&errs.push(m.text()));
page.on("pageerror",e=>errs.push(String(e)));
for (let i=0;i<puzzles.length;i++){
  await page.goto(base+`/?puzzle=${i+1}`);
  const sol=puzzles[i].solution;
  for (let k=0;k<sol.length;k+=2){
    const m=sol[k];
    await page.locator(`[data-square="${m.slice(0,2)}"]`).click();
    await page.locator(`[data-square="${m.slice(2,4)}"]`).click();
    if (m.length>4) await page.getByTestId("promotion").locator(`[data-piece="${m[4]}"]`).click();
    if (k+1<sol.length) await page.waitForTimeout(700);
  }
  const ok = await page.getByTestId("puzzle-solved").isVisible();
  console.log(i+1, puzzles[i].type, sol.join(" "), ok?"OK":"FAIL");
}
console.log("overflow", await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth));
console.log("bg", await page.evaluate(()=>getComputedStyle(document.body).backgroundColor));
// touch drag via CDP
await page.goto(base+"/");
const cdp = await ctx.newCDPSession(page);
const c=async s=>{const r=await page.locator(`[data-square="${s}"]`).boundingBox();return {x:r.x+r.width/2,y:r.y+r.height/2}};
const a=await c("e2"), t=await c("e4");
await cdp.send("Input.dispatchTouchEvent",{type:"touchStart",touchPoints:[a]});
for(let s=1;s<=5;s++) await cdp.send("Input.dispatchTouchEvent",{type:"touchMove",touchPoints:[{x:a.x+(t.x-a.x)*s/5,y:a.y+(t.y-a.y)*s/5}]});
await cdp.send("Input.dispatchTouchEvent",{type:"touchEnd",touchPoints:[]});
console.log("touch drag e4 pawn", await page.locator('[data-square="e4"] [data-piece="wP"]').count());
console.log("errors", errs);
await b.close();
EOF
(npm run dev >/tmp/chk/dev.log 2>&1 & echo $! >/tmp/chk/pid); sleep 3; cat /tmp/chk/dev.log; node /tmp/chk/check.mjs
